"""Compile source metadata into an explicitly unqualified candidate registry."""
from pathlib import Path
import json
from collect_metadata import ROOT, IDS

COMMON_UNKNOWN = {'arabic_task_success': None, 'gui_grounding_accuracy': None, 'complete_task_success': None, 'warm_latency_ms': None, 'cold_latency_ms': None, 'runtime_residency_bytes': None, 'gpu_seconds_per_verified_task': None, 'cost_per_verified_task_usd': None}
NOTES = {
 'Qwen/Qwen3.5-4B': {'role':['HalaMind','HalaType'], 'base':['Qwen/Qwen3.5-4B-Base'], 'runtime_requirement':'Qwen3_5 architecture support; card/config version strings are not an independently validated minimum. Must qualify pinned Transformers/vLLM/SGLang build.', 'arabic':'Vendor claims 201 languages/dialects; Arabic and RTL task quality unmeasured.', 'quantization':'Candidate for 8/4-bit experiments; no quantized variant evaluated.', 'gui':'General visual-agent claim; Hala tasks unmeasured.'},
 'Qwen/Qwen3-VL-2B-Instruct': {'role':['HalaMind','HalaType'], 'base':[], 'runtime_requirement':'Card originally recommends Transformers 4.57.0; PyPI 4.57.6 exists as a bounded baseline candidate, not a tested runtime.', 'arabic':'Vendor claims multilingual OCR in 32 languages; Arabic-specific performance unmeasured.', 'quantization':'Candidate for quantization after FP16 baseline.', 'gui':'Vendor visual-agent and grounding claim; Hala tasks unmeasured.'},
 'Hcompany/Holo-3.1-4B': {'role':['HalaMind','HalaType'], 'base':['Qwen/Qwen3.5-4B'], 'runtime_requirement':'Config authored with Transformers 5.6.2; Qwen3_5ForConditionalGeneration. Config float32 conflicts with BF16 stored weights; load dtype must be explicit.', 'arabic':'Card language en; Arabic retention after post-training unknown.', 'quantization':'Family announces quantization for 35B first; exact compact quantized artifact not investigated.', 'gui':'Computer-use specialized; vendor benchmarks depend on harness.', 'ancestry_warning':'Card lists four family base models; API collapsed base_model to 0.8B. 4B specific ancestry inferred from family naming/config, not independently proven.'},
 'Hcompany/Holo-3.1-0.8B': {'role':['HalaType'], 'base':['Qwen/Qwen3.5-0.8B'], 'runtime_requirement':'Config authored with Transformers 5.6.2; Qwen3_5ForConditionalGeneration. Explicit dtype required: config float32, stored weights BF16.', 'arabic':'Card language en; Arabic-specific performance unknown.', 'quantization':'Compact artifact conversion unqualified.', 'gui':'Computer-use specialized; first candidate for a small separate Type baseline.'},
 'showlab/ShowUI-2B': {'role':['HalaType'], 'base':['Qwen/Qwen2-VL-2B-Instruct'], 'runtime_requirement':'Qwen2VLForConditionalGeneration, Qwen2VLProcessor, qwen-vl-utils. Config authored with 4.45.0.dev0; exact compatible build needs qualification.', 'arabic':'Arabic-specific capability unknown.', 'quantization':'No evaluated artifact.', 'gui':'Grounding outputs relative [0,1] points; navigation action/value/position dict. Never eval generated text.', 'warning':'Official checkpoint stores pytorch_model.bin; no safetensors artifact in root tree. Review safe weight loading and exact dependency versions before loading. Weight card declares MIT while source LICENSE at 21ed7cb24be0cc877bb8352ee34d58a9aea2c876 is Apache-2.0; these are different artifact scopes, not one interchangeable license.'},
 'Qwen/Qwen3-VL-4B-Instruct': {'role':['HalaMind','HalaType'], 'base':[], 'runtime_requirement':'Same Qwen3VL processor/model family as 2B; larger residency.', 'arabic':'Multilingual OCR claim; Arabic-specific performance unmeasured.', 'quantization':'Candidate after FP16 baseline.', 'gui':'General visual-agent and grounding claim.'},
 'Hcompany/Holo4-35B-A3B': {'role':['research_baseline'], 'base':['Qwen/Qwen3.6-35B-A3B'], 'runtime_requirement':'Qwen3_5MoeForConditionalGeneration; config authored with Transformers 5.6.2. ~35.1B resident parameters despite ~3B active.', 'arabic':'Arabic-specific benchmark evidence not found.', 'quantization':'Official BF16, FP8, NVFP4 and Q4 GGUF variants announced; this pin is BF16 only.', 'gui':'Vendor OSWorld 80.8%, OSWorld2 12.3% full success in their harness; neither is Hala qualification.'},
 'LiquidAI/d1-omni-600M': {'role':['HalaReliance'], 'base':['LiquidAI/LFM2.5-Encoder-350M'], 'runtime_requirement':'Card requires transformers>=5.15, torch, torchvision, pillow, soundfile. AutoModel trust_remote_code=True; vendor CPU float32/GPU float16, avoid BF16. Exact remote code review required.', 'arabic':'Card lists ar for text; audio trained on English requests, <=30s clips.', 'quantization':'Quantization requires calibration; no qualified low-bit runtime.', 'gui':'Single-pass decisions, not action generation; advisory routing only.'},
 'LiquidAI/d1-3B': {'role':['HalaReliance_comparison'], 'base':['LiquidAI/LFM2.5-VL-3B'], 'runtime_requirement':'Card requires transformers>=5.14. AutoModel with custom decision code; CPU float32/GPU BF16 recommended by vendor, hardware dependent.', 'arabic':'Card lists ar; Hala Arabic routing quality unmeasured.', 'quantization':'No qualified low-bit runtime.', 'gui':'Typed decisions over text/images, not general chat or completion authority.'},
}

def main():
    rows=[]
    for repo in IDS:
        dest=ROOT/repo.replace('/','--')
        h=json.loads((dest/'hub.json').read_text(encoding='utf-8'))
        c=json.loads((dest/'config.json').read_text(encoding='utf-8'))
        tree=json.loads((dest/'tree.json').read_text(encoding='utf-8'))
        card=h.get('cardData',{})
        lic=card.get('license')
        weights=[x for x in tree if x.get('path','').endswith('.safetensors') or x.get('path','')=='pytorch_model.bin']
        count=h.get('safetensors',{}).get('total')
        proc={name:json.loads((dest/name).read_text(encoding='utf-8')) for name in ['preprocessor_config.json','processor_config.json'] if (dest/name).exists()}
        extras=NOTES[repo]
        licensed='conditional-commercial' if repo.startswith('LiquidAI/') else 'declared-permissive-commercial'
        license_notes='LFM Open License v1.0: commercial grant subject to $10M annual-revenue threshold; entities exceeding threshold not licensed. Threshold defined as $10M or more while operative clause says exceeds: do not assume eligibility at boundary. Aggregate Legal Entity/control definition applies. Redistribution sections 4(a-d): copy license, mark changes, retain notices and NOTICE. Nonprofit exception only non-commercial/research. No trademark grant.' if repo.startswith('LiquidAI/') else ('MIT declaration for derived checkpoint; Qwen2-VL base Apache-2.0 declaration must also be retained. No standalone MIT license file in checkpoint root.' if repo.startswith('showlab/') else 'Apache-2.0 declaration: commercial use, modification and redistribution permitted subject to license copy, change notices, applicable attribution/NOTICE and patent conditions; no trademark permission. Some checkpoint roots omit full LICENSE; preserve pinned declaration plus standard text.')
        base=[]
        for bid in extras['base']:
            bd=ROOT/bid.replace('/','--')
            bh=json.loads((bd/'hub.json').read_text(encoding='utf-8')) if (bd/'hub.json').exists() else {}
            base.append({'id':bid,'revision':bh.get('sha'),'license':bh.get('cardData',{}).get('license'),'provenance':'research/evidence/'+bd.name+'/provenance.json' if bh else None})
        bounds={name:round(count*bytes_per,0) if count else None for name,bytes_per in [('fp16',2),('int8',1),('int4',0.5)]}
        row={'id':repo,'revision':h['sha'],'source':f'https://huggingface.co/{repo}/tree/{h["sha"]}','status':'unqualified','roles':extras['role'],'license':lic,'license_status':licensed,'license_notes':license_notes,'standalone_license_files':[x['path'] for x in tree if x.get('path') in ['LICENSE','LICENSE.md','LICENSE.txt']],'base_models':base,'base_model_card_declaration':card.get('base_model'),'architecture':c.get('architectures'),'model_type':c.get('model_type'),'parameters':{'advertised_name':repo.split('/')[-1],'hub_tensor_count':count,'stored_dtypes':h.get('safetensors',{}).get('parameters'),'note':'Total tensor count includes vision/auxiliary modules; product size label is not exact residency.'},'weight_artifacts':[{k:x.get(k) for k in ['path','size','lfs']} for x in weights],'weights_disk_bytes':sum(x['size'] for x in weights) if weights else None,'processor':proc,'image_inputs':'Processor supports RGB/PIL-decoded screenshots; JPEG/PNG container acceptance and resize coordinate mapping require runtime tests. No universal fixed screenshot size.','tool_format':'d1 named noul/choice/score Decision Index questions and probability answers, zero output tokens.' if repo.startswith('LiquidAI/') else ('Native function calls plus structured JSON per Hcompany docs; schema adapter must restrict to Aladdin vocabulary.' if repo.startswith('Hcompany/') else 'Prompt/chat-template output requires strict schema adapter; model text is untrusted.'),'runtime_requirement':extras['runtime_requirement'],'runtime_compatibility_tested':False,'training_feasibility':'LoRA/SFT is a proposed bounded remote experiment; not trained. Exact target modules, optimizer memory, image budget and runtime support must be checked.' if not repo.startswith('LiquidAI/') else 'Specialist decision adaptation research only; no reproduced training pipeline. Compare deterministic routing and independently trained sub-600M classifier.','weight_memory_lower_bounds_bytes':bounds,'memory_estimate_scope':'Storage-only ideal bit-width arithmetic on TOTAL tensor count. Excludes quantization scales, non-quantized towers, activations, KV/state caches, runtime allocation and allocator fragmentation. Not GPU requirements.','gpu_requirements_measured':None,'arabic_evidence':extras['arabic'],'gui_evidence':extras['gui'],'quantization_evidence':extras['quantization'],'measurements':dict(COMMON_UNKNOWN),'provenance':{'hub_api':f'https://huggingface.co/api/models/{repo}','pinned_files_manifest':'research/evidence/'+dest.name+'/provenance.json','tree_api':f'https://huggingface.co/api/models/{repo}/tree/{h["sha"]}'}}
        for key in ['ancestry_warning','warning']:
            if key in extras: row[key]=extras[key]
        rows.append(row)
    out={'schema_version':1,'observed_at':'2026-10-14','evidence_kind':'official metadata only; no local weights, no performance qualification','provisional_foundation':'Qwen/Qwen3.5-4B','first_runtime_baseline':'Qwen/Qwen3-VL-2B-Instruct','decision_scope':'Provisional experiment ordering, not adoption or commercial release approval. Deterministic routing baseline remains default.','candidates':rows}
    dest=Path(__file__).parent.parent/'hala/models/registry.json'
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8',newline='\n')
    print('Wrote',len(rows),'candidates;',sum(1 for x in rows if x['status']=='unqualified'),'unqualified.')

if __name__=='__main__': main()
